import { createHash } from "node:crypto";
import { encodeFunctionData } from "viem";
import { entryPoint06Address } from "viem/account-abstraction";
import { nonceAbi } from "./alchemy-executor.js";
import { transactionFingerprint, type NormalizedCall, type WalletNetwork } from "./transaction-builder.js";
import type { CancelPlan } from "./wallet-store.js";
export function cancellationCalls(plan: CancelPlan): NormalizedCall[] {
  // All operations generated by this executor use lane 0. Lane 1 is reserved
  // for cancellation, avoiding a replacement at the original pending nonce.
  const nonce = BigInt(plan.targetNonce);
  if (nonce < 0n || nonce >= 2n ** 64n || plan.entryPoint.toLowerCase() !== entryPoint06Address.toLowerCase()) throw new Error("unsupported cancellation nonce or EntryPoint");
  return [{ to: entryPoint06Address, value: "0", data: encodeFunctionData({ abi: nonceAbi, functionName: "incrementNonce", args: [0n] }) }];
}
export function cancellationFingerprint(network: WalletNetwork, address: `0x${string}`, plan: CancelPlan) {
  return createHash("sha256").update(JSON.stringify([transactionFingerprint(network, address, cancellationCalls(plan)), plan.targetId, plan.targetHash.toLowerCase(), plan.targetNonce, plan.entryPoint.toLowerCase(), plan.fromBlock, ...(plan.replaces ? [plan.replaces.id, plan.replaces.nonce, plan.replaces.maxFeePerGas, plan.replaces.maxPriorityFeePerGas] : [])])).digest("hex");
}
